//! Framework-independent responses generated by authentication and authorization.

use bytes::Bytes;
use http::{Response, StatusCode};

/// A buffered security response, independent of a web framework's body type.
///
/// The default conversion maps this body's bytes into the inner service's body through
/// `From<Bytes>`. [`crate::SecurityLayer::response_adapter`] can customize the entire response.
/// Successful inner responses are forwarded unchanged, including streaming bodies.
///
/// ```
/// use tower_http_access::SecurityResponse;
/// use bytes::Bytes;
/// use http::StatusCode;
///
/// let response: SecurityResponse = http::Response::builder()
///     .status(StatusCode::UNAUTHORIZED)
///     .header("www-authenticate", "Basic realm=\"Notes\"")
///     .body(Bytes::from_static(b"Authentication required"))?;
/// # Ok::<(), http::Error>(())
/// ```
pub type SecurityResponse = Response<Bytes>;

/// Converts a security-generated HTTP response into a response for another body type or protocol.
///
/// The adapter owns the input response and can translate its status, headers, extensions, and body.
/// Unlike a body-only conversion, it can change the meaning of the response for a target protocol.
/// Successful application responses should bypass this conversion so streaming bodies remain
/// untouched. Adapters format a rejection; they do not authenticate identities or decide access.
///
/// For example, an HTTP-to-gRPC adapter could translate these security failures:
///
/// | HTTP status | gRPC status |
/// | --- | --- |
/// | 401 Unauthorized | `Unauthenticated` |
/// | 403 Forbidden | `PermissionDenied` |
/// | 500 Internal Server Error | `Internal` |
///
/// Such an adapter must construct a gRPC response, including the appropriate `content-type` and
/// gRPC status metadata, rather than merely copying the HTTP status or wrapping the body bytes.
/// With Tonic, [`Status::into_http`](https://docs.rs/tonic/latest/tonic/struct.Status.html#method.into_http)
/// can construct that response. The adapter chooses how to handle custom statuses, messages,
/// and metadata; arbitrary HTTP error bodies are not gRPC-encoded messages.
///
/// Configure an adapter with [`crate::SecurityLayer::response_adapter`]. The combined layer invokes
/// it for all security rejections; successful inner responses bypass it. The default
/// [`DefaultSecurityResponseAdapter`] preserves HTTP metadata and converts only the body through
/// `From<Bytes>`. No protocol-specific adapters are supplied. The standalone authentication and
/// authorization layers continue to use their existing `From<Bytes>` conversion.
///
/// ```
/// use tower_http_access::{SecurityResponse, SecurityResponseAdapter};
///
/// fn convert<B>(
///     adapter: &impl SecurityResponseAdapter<B>,
///     response: SecurityResponse,
/// ) -> http::Response<B> {
///     adapter.adapt(response)
/// }
/// ```
pub trait SecurityResponseAdapter<B> {
    /// Consume a security response and produce the target HTTP response representation.
    fn adapt(&self, response: SecurityResponse) -> Response<B>;
}

/// Default HTTP conversion for [`crate::SecurityLayer`].
///
/// Preserves the status, headers, and extensions, converting only the buffered response body.
#[derive(Clone, Copy, Debug, Default)]
pub struct DefaultSecurityResponseAdapter;

impl<B: From<Bytes>> SecurityResponseAdapter<B> for DefaultSecurityResponseAdapter {
    fn adapt(&self, response: SecurityResponse) -> Response<B> {
        response.map(B::from)
    }
}

pub(crate) fn empty_response(status: StatusCode) -> SecurityResponse {
    let mut response = Response::new(Bytes::new());
    *response.status_mut() = status;
    response
}

#[cfg(test)]
pub(crate) fn test_response(status: StatusCode, body: impl Into<Bytes>) -> SecurityResponse {
    let mut response = Response::new(body.into());
    *response.status_mut() = status;
    response
}

